// Web only: the grammar lessons are not in the web bundle (it would pass Cloudflare's 25 MiB asset limit). The `<x>.index.web.ts`
// twins (generated by scripts/gen-content-index.mjs) read them from here instead: one static JSON per pack,
// dist/content/<pack>.json (scripts/build-web-content.mjs), fetched by the web gate (components/cloud/CloudGate.tsx) before the app mounts.
import { WEB_PACKS } from './webPacks.generated';

const cache = new Map<string, Record<string, unknown>>();
let inflight: Promise<void> | null = null;

/** One entry of a loaded pack (a lesson, or a sidecar), synchronously; throws if the pack is not loaded yet. */
export function packEntry<T>(pack: string, id: string): T {
  const entries = cache.get(pack);
  if (!entries) throw new Error(`web content pack ${pack} not loaded`);
  if (!(id in entries)) throw new Error(`web content pack ${pack} has no entry ${id}`);
  return entries[id] as T;
}

/** Fetches every pack in parallel. Runs once (later calls get the same promise); after a failure the next call tries again. */
export function prefetchContentPacks(): Promise<void> {
  if (!inflight) {
    const run = Promise.all(
      WEB_PACKS.map(async ({ name }) => {
        // no-cache: the pack's URL stays the same across deploys, so the browser revalidates it (a 304 when unchanged) instead of
        // serving an old pack to a new bundle
        const res = await fetch(`/content/${name}.json`, { cache: 'no-cache' });
        if (!res.ok) throw new Error(`web content pack ${name}: HTTP ${res.status}`);
        cache.set(name, (await res.json()) as Record<string, unknown>);
      }),
    ).then(() => undefined);
    inflight = run;
    run.catch(() => {
      if (inflight === run) inflight = null;
    });
  }
  return inflight;
}
